head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");


//수정요청 창에 넘겨주기 위한 변수
scwin.clickBzProcsNo = "";
scwin.clickIsuCd = "";
scwin.clickIsuNm = "";
scwin.clickIntegUsrId = "";
scwin.clickIntegUsrNm = "";
scwin.pMenuID = $c.cm.InfoMenuID();
//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.pMngId = js_id;
scwin.fn_GetPar, scwin.fn_SetPar; // 종목 파라미터
scwin.fn_GetParIsur, scwin.fn_SetParIsur; // 상장신청인 파라미터

scwin.vScrenID = "ULDSTF70070.xml";
scwin.fr_queryId; // 종목 query id 
scwin.fn_pGubun; // 신규팝업 구분값('I':신규,'D':삭제)

String.prototype.trim = function() {
    return this.replace(/(^\s*)|(\s*$)/gi, "");
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};


// 종목
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션		
    arrPar[0] = ""; //getObjectValue(txb_ISU_CD); 	// 코드값을 포함할 컨트롤
    //	arrPar[3] = getObjectValue(txb_ISU_NM);	    // 명칭값을 포함할 컨트롤	
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};



//상장신청인
scwin.fn_GetParUsrId = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_INTEG_USR_ID); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_EMP_NM); // 명칭값을 포함할 컨트롤	
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParUsrId = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_INTEG_USR_ID.setValue(arrPar[0].ISU_CD);
        txb_EMP_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};
scwin.fn_list_sync = function() {
    //alert(fr_MktId);
    var isuCd = $c.stf.getObjectValue(txb_ISU_CD).trim(); // 종목코드
    var IntegUsrId = $c.stf.getObjectValue(txb_INTEG_USR_ID).trim(); // 상장신청인id

    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listDigitalAinvst";
    url += "&LD_MKT_TP=" + scwin.fr_MktId;
    url += "&ISU_CD=" + isuCd;
    url += "&INTEG_USR_ID=" + IntegUsrId;
    url += "&STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&END_DD=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_setBzProcsNo = function(obj) {
    if (obj > -1) {
        // view or delete 에만 값전달
        scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
        scwin.clickIsuCd = dts_List.getCellData(eval(obj), "ISU_CD");
        scwin.clickIsuNm = dts_List.getCellData(eval(obj), "ISUR_CD_NM");
        scwin.clickIntegUsrId = dts_List.getCellData(eval(obj), "INTEG_USR_ID");
        scwin.clickIntegUsrNm = dts_List.getCellData(eval(obj), "INTEG_USR_NM");
    } else {
        // 신규일 경우에 값 전달X
        scwin.clickBzProcsNo = "";
        scwin.clickIsuCd = "";
        scwin.clickIsuNm = "";
        scwin.clickIntegUsrId = "";
        scwin.clickIntegUsrNm = "";
    }
};
scwin.fn_OpenDetail = async function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    }
    dts_CalCul.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LISTING_COUNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.digital.select.bzProcsCnt.condition" + "&{P}param01=" + scwin.clickIsuCd;
    dts_CalCul.DataID = encodeURI(url);
    dts_CalCul.reset();
    var gCnt = -1;
    dts_CalCul.insertRow();
    gCnt = dts_CalCul.getCellData(1, "CNT");
    var pTitleName = "";
    if (gCnt > 0) {
        // 디지털증권상장신청 테이블에 데이터가 존재할 시 ,
        // 삭제처리 불가능

        scwin.fn_pGubun = "V";
        pTitleName = "신청계획등록";
    } else {
        // 디지털증권상장신청 테이블에 데이터가 존재할 시 ,
        // 삭제처리 가능

        scwin.fn_pGubun = "D";
        pTitleName = "신청계획등록 삭제";
    }
    await $c.frame.CreateDialogFrame("ULDSTF70071.gfm", "/digital/ULDSTF70071.gfm", pTitleName, 10, 10, 540, 180, "window");
};
scwin.btn_Search_onclick = function() {
    /*
    f (getObjectValue(txb_ISUR_CD) == "") {
    	alert("[회사]를 선택하세요.");txb_ISUR_CD.focus();return;
    }
    */
    scwin.fn_list_sync();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "신청계획등록(신탁수익증권)", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    //fn_GetPar = fn_GetParDetail; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    //fn_SetPar = undefined;

    scwin.fn_OpenDetail(row);
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    //PanelToGroupBox(panel_Top);	
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.img_SearchIsu_onclick = async function() {
    //종목 선택
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    scwin.fr_queryId = "lds.stf.digital.select.secuisuall_p1.condition";
    await $c.frame.CreateDialogFrame("ULDSTF70017_3.gfm", "../digital/ULDSTF70017_3.gfm", "종목 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.img_SearchUrs_onclick = async function() {
    // 상장신청인 선택
    scwin.fn_GetParIsur = fn_GetParUsrId;
    scwin.fn_SetParIsur = fn_SetParUsrId;
    await $c.frame.CreateDialogFrame("ULDSTF70017_4.gfm", "../digital/ULDSTF70017_4.gfm", "상장신청인 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.btn_New_onclick = async function() {
    scwin.fn_pGubun = "I";
    scwin.fn_setBzProcsNo(-1);
    await $c.frame.CreateDialogFrame("ULDSTF70071.gfm", "../digital/ULDSTF70071.gfm", "신규 등록", 10, 10, 540, 180, "window");

    // 재조회
    scwin.fn_list_sync();
};
scwin.txb_ISU_CD_onchange = function() {
    $c.stf.setObjectValue(txb_ISU_NM, "");
};
scwin.txb_INTEG_USR_ID_onchange = function() {
    $c.stf.setObjectValue(txb_EMP_NM, "");
};
